export const SYNC_FILE='retomar.enc.json';
export class RemoteError extends Error{constructor(message,{retryable=false,delay=0,status=0}={}){super(message);this.retryable=retryable;this.delay=delay;this.status=status}}
export function parseGistId(value){const text=String(value||'').trim();if(!text)return '';let id=text;if(text.startsWith('https://')){let u;try{u=new URL(text)}catch{throw Error('Informe um ID ou endereço válido do Gist.')}if(u.hostname!=='gist.github.com'||u.search||u.hash)throw Error('Use o endereço de um Gist do GitHub.');id=u.pathname.split('/').filter(Boolean).at(-1)}if(!/^[a-f0-9]{5,64}$/i.test(id))throw Error('O ID do Gist é inválido.');return id.toLowerCase()}
export class GistAdapter{
  constructor(token,{fetchImpl=globalThis.fetch}={}){if(typeof token!=='string'||!token.trim()||/[\r\n]/.test(token))throw Error('Informe um token válido do GitHub.');this.token=token.trim();this.fetch=fetchImpl.bind(globalThis)}
  async request(path,{method='GET',body,signal}={}){
    const controller=new AbortController(),abort=()=>controller.abort();if(signal?.aborted)throw new DOMException('Cancelado','AbortError');signal?.addEventListener('abort',abort,{once:true});const timeout=setTimeout(abort,20000);
    try{const r=await this.fetch('https://api.github.com'+path,{method,headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+this.token,'X-GitHub-Api-Version':'2026-03-10',...(body?{'Content-Type':'application/json'}:{})},cache:'no-store',redirect:'error',signal:controller.signal,...(body?{body:JSON.stringify(body)}:{})});
      if(!r.ok){if(r.status===401)throw new RemoteError('O token do GitHub é inválido ou expirou. Atualize a conexão.');if(r.status===404)throw new RemoteError('O Gist não foi encontrado ou o token não tem acesso.',{status:404});if(r.status===403||r.status===429){const limited=r.status===429||r.headers.get('x-ratelimit-remaining')==='0';const wait=Number(r.headers.get('retry-after')||0)*1000,reset=Number(r.headers.get('x-ratelimit-reset')||0)*1000-Date.now();throw new RemoteError(limited?'O limite de requisições do GitHub foi atingido. Tente mais tarde.':'O GitHub recusou a operação. Confira a permissão de Gists do token.',{retryable:limited,delay:Math.min(86400000,Math.max(60000,Number.isFinite(wait)?wait:0,Number.isFinite(reset)?reset:0))})}throw new RemoteError(r.status>=500?'O GitHub está indisponível. Os dados locais foram mantidos.':'O GitHub não aceitou a sincronização. Confira a conexão.',{retryable:r.status>=500})}
      const data=await r.json();return data;
    }catch(e){if(e instanceof RemoteError)throw e;if(signal?.aborted)throw new DOMException('Cancelado','AbortError');throw new RemoteError('Não foi possível acessar o GitHub. Os dados continuam neste aparelho.',{retryable:true})}finally{clearTimeout(timeout);signal?.removeEventListener('abort',abort)}
  }
  async discover(signal){const found=[];for(let page=1;page<=10;page++){const list=await this.request('/gists?per_page=100&page='+page,{signal});if(!Array.isArray(list))throw new RemoteError('O GitHub retornou uma lista inválida.');for(const g of list)if(g.public===false&&g.files?.[SYNC_FILE])found.push({id:parseGistId(g.id),updatedAt:g.updated_at});if(list.length<100)return found}throw new RemoteError('Não foi possível concluir a busca nesta conta: há mais de 1.000 Gists. Nenhum novo backup foi criado.');}
  async read(id,signal){const g=await this.request('/gists/'+parseGistId(id),{signal});const file=g.files?.[SYNC_FILE];if(g.public!==false)throw new RemoteError('Escolha um Gist secreto do Retomar.');if(!file)throw new RemoteError('Este Gist não contém um backup do Retomar.');if(g.truncated||file.truncated||typeof file.content!=='string'||file.size>950000||file.content.length>950000)throw new RemoteError('O GitHub retornou um arquivo incompleto ou grande demais. Nenhum dado foi aplicado.');return file.content;}
  async create(content,signal){const g=await this.request('/gists',{method:'POST',body:{description:'Retomar · backup criptografado',public:false,files:{[SYNC_FILE]:{content}}},signal});if(g.public!==false||!g.id)throw new RemoteError('O destino não foi criado como um Gist secreto.');return parseGistId(g.id);}
  async write(id,content,signal){await this.request('/gists/'+parseGistId(id),{method:'PATCH',body:{files:{[SYNC_FILE]:{content}}},signal});}
}
